#include <bits/stdc++.h>
using namespace std;

static char buf[1 << 16];
static size_t blen = 0, bpos = 0;
static inline int gc() {
    if (bpos == blen) {
        blen = fread(buf, 1, sizeof buf, stdin);
        bpos = 0;
        if (!blen) return -1;
    }
    return buf[bpos++];
}
static long long readLong() {
    int c = gc();
    while (c != '-' && (c < '0' || c > '9')) {
        if (c == -1) return 0;
        c = gc();
    }
    bool neg = false;
    if (c == '-') { neg = true; c = gc(); }
    long long v = 0;
    while (c >= '0' && c <= '9') { v = v * 10 + (c - '0'); c = gc(); }
    return neg ? -v : v;
}

int main() {
    int n = (int)readLong(), k = (int)readLong();
    vector<long long> a(n);
    for (auto &v : a) v = readLong();
    // a[i] becomes the total collected when starting at i.
    for (int i = n - k - 1; i >= 0; i--) a[i] += a[i + k];
    printf("%lld\n", *max_element(a.begin(), a.end()));
}

import java.io.*;

public class Main {
    static final InputStream in = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int gc() throws IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = gc();
        while (c != '-' && (c < '0' || c > '9')) {
            if (c == -1) return 0;
            c = gc();
        }
        boolean neg = false;
        if (c == '-') { neg = true; c = gc(); }
        long v = 0;
        while (c >= '0' && c <= '9') { v = v * 10 + (c - '0'); c = gc(); }
        return neg ? -v : v;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), k = (int) nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // a[i] becomes the total collected when starting at i.
        for (int i = n - k - 1; i >= 0; i--) a[i] += a[i + k];
        long best = a[0];
        for (long v : a) best = Math.max(best, v);
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<16)

func readInt() int64 {
	c, err := rd.ReadByte()
	for err == nil && c != '-' && (c < '0' || c > '9') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return 0
	}
	neg := false
	if c == '-' {
		neg = true
		c, err = rd.ReadByte()
	}
	var v int64
	for err == nil && c >= '0' && c <= '9' {
		v = v*10 + int64(c-'0')
		c, err = rd.ReadByte()
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	n, k := int(readInt()), int(readInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = readInt()
	}
	// a[i] becomes the total collected when starting at i.
	for i := n - k - 1; i >= 0; i-- {
		a[i] += a[i+k]
	}
	best := a[0]
	for _, v := range a {
		best = max(best, v)
	}
	fmt.Println(best)
}
